def finding(item, ordinal, refs):
    fid, name, primary = item
    low = name.lower()
    kinds = [primary, KINDS[(ordinal + 7) % len(KINDS)], KINDS[(ordinal + 15) % len(KINDS)]]
    return {"id": fid, "name": name,
            "description": f"Records {low} as source-qualified Insurance Claim context while policy, occurrence, party, subject, evidence, handling, decision, settlement, payment, complaint, dispute, fraud, recovery, audit and records masters remain external.",
            "source_refs": refs,
            "questions": [
                {"id": f"{fid}-q01", "text": f"Which stable claim, version, claim class, insurance basis, loss, jurisdiction and master-system identities establish {low}?", "kind": kinds[0], "answer_data": ["claim and version identifiers, claim use, insurance line, jurisdiction, master system and predecessor or successor", "policy, scheme, coverage, loss occurrence, insured-interest and handling-case references", "source, status, effective period, received time, event time, knowledge time and confidence"]},
                {"id": f"{fid}-q02", "text": f"Who asserted, submitted, owns, stewards, validates, contests or may access {low}, under what authority and purpose?", "kind": kinds[1], "answer_data": ["claimant, insured, policyholder, beneficiary, injured party, provider, representative, insurer, handler, reviewer and regulator roles", "assertion owner, source, mandate, policy term, law, consent, purpose, access scope, confidentiality and privilege", "accepted, disputed, corrected, withdrawn, superseded or unresolved position and responsible authority"]},
                {"id": f"{fid}-q03", "text": f"Which occurrence, item, quantity, amount, evidence, decision, event time, uncertainty, contradiction and lineage qualify {low}?", "kind": kinds[2], "answer_data": ["occurrence, peril, cause, damage, injury, expense, service, benefit, claim-line and amount assertions", "document, observation, statement, method, evidence source, completeness, quality, uncertainty and conflict", "handling, coverage decision, offer, settlement, payment, complaint, dispute, recovery and regulator references without ownership transfer"]}],
            "data_elements": [{"id": f"{fid}-data", "name": f"{name} data", "description": f"Typed claim data for {low}, qualified by assertion owner, source, authority, insurance basis, event and knowledge times, uncertainty, access and provenance.", "value_kind": "object", "cardinality": "1", "required": True, "source_refs": refs}],
            "artifacts": [{"id": f"{fid}-record", "name": f"{name} record", "description": f"Immutable or versioned evidence for {low} with claim identity, digest, source, assertion class, event and knowledge times, access marking and successor lineage.", "media_or_form": ["application/yaml", "application/json", "application/pdf", "text/csv", "text/markdown", "text/html"], "serial": True, "identity_strategy": "Prefer the authoritative insurer, scheme, provider, claimant portal, regulator or records identifier; otherwise use a governed IRI, then a Dimension UUID or ULID.", "source_refs": refs}],
            "inline_only_rationale": None}


def structure():
    bundles, ordinal = [], 0
    for bid, bname, rationale, layer_rows in ROWS:
        layers, bundle_refs = [], []
        for lid, lname, refs, items in layer_rows:
            bundle_refs.extend(refs)
            fs = []
            for item in items:
                ordinal += 1
                fs.append(finding(item, ordinal, refs))
            layers.append({"id": lid, "name": lname, "description": f"Groups governed assertions about {lname.lower()} for an insurance claim.", "source_refs": refs, "findings": fs})
        bundles.append({"id": bid, "name": bname, "description": rationale, "rationale": rationale, "source_refs": list(dict.fromkeys(bundle_refs)), "layers": layers})
    return {"bundles": bundles}


